definition.script:
pipeline {
    agent any

    options {
        timestamps()
        ansiColor('xterm')
        disableConcurrentBuilds()
        timeout(time: 25, unit: 'MINUTES')
    }

    stages {
        stage('Sync Workspace') {
            steps {
                echo '=== Syncing files from local workspace /workspace ==='
                sh '''
                    set -e
                    rsync -av --exclude='.venv*' --exclude='node_modules' --exclude='.git' /workspace/ . || cp -rf /workspace/* . || true
                    ls -la
                '''
            }
        }

        stage('Lint & Unit Tests') {
            steps {
                sh '''
                    set -eux
                    python3 -m venv .venv-ci
                    . .venv-ci/bin/activate
                    pip install --upgrade pip setuptools wheel --quiet
                    pip install -r requirements.txt --quiet
                    pip install flake8 black isort pytest pytest-cov pytest-asyncio httpx --quiet
                    black --check --diff services/ ml/ || true
                    flake8 services/ ml/ --max-line-length=100 --exclude=__pycache__,.venv,.venv-ci,migrations --ignore=E203,W503 || true
                    mkdir -p test-results
                    python3 -m pytest tests/unit/ -v --tb=short --junitxml=test-results/unit-results.xml || true
                '''
            }
            post {
                always {
                    junit testResults: 'test-results/unit-results.xml', allowEmptyResults: true
                    archiveArtifacts artifacts: 'test-results/**', allowEmptyArchive: true
                }
            }
        }

        stage('Build Frontend') {
            steps {
                sh '''
                    set -eux
                    cd services/dashboard-frontend
                    npm install --prefer-offline --no-audit || npm install
                    npm run build
                '''
            }
            post {
                success {
                    archiveArtifacts artifacts: 'services/dashboard-frontend/dist/**', allowEmptyArchive: true
                }
            }
        }

        stage('Train ML Model') {
            steps {
                sh '''
                    set -eux
                    . .venv-ci/bin/activate
                    python3 ml/train.py
                '''
            }
            post {
                success {
                    archiveArtifacts artifacts: 'ml/models/**', allowEmptyArchive: true
                }
            }
        }

        stage('Build Docker Images') {
            steps {
                sh '''
                    set -eux
                    for svc in log-ingestion-api log-processor ml-engine alert-service dashboard-backend; do
                        echo "Building logsentinel-${svc}..."
                        docker build -t logsentinel/${svc}:local-ci services/${svc}/ || true
                    done
                '''
            }
        }

        stage('Health Check') {
            steps {
                sh '''
                    set +e
                    echo "Checking running microservices on Docker network..."
                    curl -sf http://log-ingestion-api:8000/health && echo "  ✔ log-ingestion-api OK" || echo "  ✘ log-ingestion-api not reachable (verify docker compose up)"
                    curl -sf http://ml-engine:8001/health && echo "  ✔ ml-engine OK" || echo "  ✘ ml-engine not reachable"
                    curl -sf http://dashboard-backend:8002/health && echo "  ✔ dashboard-backend OK" || echo "  ✘ dashboard-backend not reachable"
                '''
            }
        }
    }

    post {
        success {
            echo 'LogSentinel Pipeline completed successfully!'
        }
        failure {
            echo 'LogSentinel Pipeline failed. Please check stage logs above.'
        }
        always {
            cleanWs(cleanWhenAborted: true, cleanWhenFailure: false, cleanWhenSuccess: true)
        }
    }
}
